import React, { useRef } from 'react';
import { MaskEditor } from 'react-canvas-masker';

function App() {
  const canvasRef = useRef(null);

  return (
    <div style={{ 
      padding: '20px', 
      maxWidth: '800px', 
      margin: '0 auto',
      fontFamily: 'Arial, sans-serif'
    }}>
      <h2 style={{ textAlign: 'center' }}>🎨 Раскрась небо!</h2>
      <p style={{ textAlign: 'center' }}>
        Проведи пальцем (или мышкой) по серому небу, чтобы раскрасить его в голубой
      </p>

      <div style={{ 
        position: 'relative',
        backgroundImage: `url('/gray.jpg')`,
        backgroundSize: 'contain',
        backgroundRepeat: 'no-repeat',
        backgroundPosition: 'center',
        border: '3px solid #ccc',
        borderRadius: '10px',
        overflow: 'hidden'
      }}>
        <MaskEditor
          src="/blue.jpg"
          canvasRef={canvasRef}
          maskColor="#000000"
          maskOpacity={1}
          cursorSize={40}
        />
      </div>

      <div style={{ 
        marginTop: '20px', 
        display: 'flex', 
        gap: '10px', 
        justifyContent: 'center' 
      }}>
        <button 
          onClick={() => {
            if (canvasRef.current) {
              canvasRef.current.clearMask();
            }
          }}
          style={{
            padding: '10px 20px',
            fontSize: '16px',
            backgroundColor: '#ff6b6b',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer'
          }}
        >
          🔄 Сбросить
        </button>
        <button 
          onClick={() => {
            alert('Молодец! Небо теперь голубое! 🌤️');
          }}
          style={{
            padding: '10px 20px',
            fontSize: '16px',
            backgroundColor: '#4ecdc4',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer'
          }}
        >
          ✅ Готово!
        </button>
      </div>
    </div>
  );
}

export default App;
